{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-kptyzP/src/parser.js","content":"/**
 * Parses the build graph text format into a graph: a map of task names to
 * their cost, and a map of task names to the (deduplicated) list of names
 * they depend on.
 */

import { lineError, unknownTaskError } from './errors.js'

const NAME_PATTERN = /^[A-Za-z0-9_.-]+$/
const COST_PATTERN = /^[0-9]+$/

export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const costs = new Map()
  const deps = new Map()
  // Names a `dep` line uses, in the order they appear across the file, for
  // the unknown-task check that runs once the whole file has been read.
  const usages = []

  lines.forEach((rawLine, index) => {
    const lineNumber = index + 1
    const line = rawLine.trim()
    if (line === '' || line.startsWith('#')) return

    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw lineError(lineNumber, 'expected task <name> <cost>')
      const [, name, cost] = words
      if (!NAME_PATTERN.test(name)) throw lineError(lineNumber, `invalid task name ${name}`)
      if (!COST_PATTERN.test(cost)) throw lineError(lineNumber, 'cost must be a non-negative integer')
      if (costs.has(name)) throw lineError(lineNumber, `task ${name} is declared twice`)
      costs.set(name, Number.parseInt(cost, 10))
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (directive === 'dep') {
      if (words.length < 3) throw lineError(lineNumber, 'expected dep <name> <dependency>...')
      const [, name, ...dependencies] = words
      for (const n of [name, ...dependencies]) {
        if (!NAME_PATTERN.test(n)) throw lineError(lineNumber, `invalid task name ${n}`)
      }
      usages.push(name, ...dependencies)
      if (!deps.has(name)) deps.set(name, new Set())
      const set = deps.get(name)
      for (const dependency of dependencies) set.add(dependency)
    } else {
      throw lineError(lineNumber, `unknown directive ${directive}`)
    }
  })

  for (const name of usages) {
    if (!costs.has(name)) throw unknownTaskError(name)
  }

  const depsArray = new Map()
  for (const [name, set] of deps) depsArray.set(name, [...set])

  return { costs, deps: depsArray }
}
"}

