{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-kptyzP/src/graph.js","content":"/**
 * Graph algorithms shared by the three reporting modes: cycle detection,
 * per-task timing/depth, and the downstream-chain priority `pack` uses.
 */

import { cycleError } from './errors.js'

function sortedDeps(deps, name) {
  return [...(deps.get(name) ?? [])].sort()
}

/**
 * Finds the first cycle a depth-first search reaches when it starts from
 * each task in ascending name order and walks dependencies in ascending
 * name order, and raises the matching CliError. Does nothing when the
 * graph is acyclic.
 */
export function checkForCycle(costs, deps) {
  const names = [...costs.keys()].sort()
  const state = new Map() // absent: unvisited, 'stack': in progress, 'done': finished

  for (const start of names) {
    if (state.get(start) === 'done') continue

    const stack = [{ node: start, index: 0, deps: sortedDeps(deps, start) }]
    state.set(start, 'stack')

    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      if (frame.index < frame.deps.length) {
        const next = frame.deps[frame.index]
        frame.index += 1
        const nextState = state.get(next)
        if (nextState === 'stack') {
          const cycleStart = stack.findIndex((f) => f.node === next)
          const cycle = stack.slice(cycleStart).map((f) => f.node)
          cycle.push(next)
          throw cycleError(cycle)
        } else if (nextState !== 'done') {
          state.set(next, 'stack')
          stack.push({ node: next, index: 0, deps: sortedDeps(deps, next) })
        }
      } else {
        state.set(frame.node, 'done')
        stack.pop()
      }
    }
  }
}

/**
 * Computes, for every task, its start, finish and wave depth with
 * unlimited workers. A task's depth is one more than the deepest depth
 * among its dependencies, or 0 when it has none.
 */
export function computeTimings(costs, deps) {
  const timings = new Map()

  function timingFor(name) {
    const cached = timings.get(name)
    if (cached) return cached
    let start = 0
    let depth = 0
    for (const dependency of deps.get(name) ?? []) {
      const dependencyTiming = timingFor(dependency)
      if (dependencyTiming.finish > start) start = dependencyTiming.finish
      if (dependencyTiming.depth + 1 > depth) depth = dependencyTiming.depth + 1
