{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-kptyzP/src/scheduler.js","content":"/**
 * Simulates the build graph on a fixed number of workers, greedily
 * preferring the ready task with the greatest priority (longest downstream
 * chain), breaking ties by ascending name.
 */

export function packSchedule(costs, deps, priorities, workerCount) {
  const names = [...costs.keys()]
  const workerLog = Array.from({ length: workerCount }, () => [])
  const workerFreeAt = new Array(workerCount).fill(0)
  const finishOf = new Map()
  const unstarted = new Set(names)
  let makespan = 0
  let time = 0

  while (unstarted.size > 0) {
    for (;;) {
      const freeWorker = workerFreeAt.findIndex((freeAt) => freeAt <= time)
      if (freeWorker === -1) break

      let best = null
      for (const name of unstarted) {
        const ready = (deps.get(name) ?? []).every((dependency) => finishOf.get(dependency) <= time)
        if (!ready) continue
        if (
          best === null ||
          priorities.get(name) > priorities.get(best) ||
          (priorities.get(name) === priorities.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const start = time
      const finish = start + costs.get(best)
      workerLog[freeWorker].push({ name: best, start, finish })
      workerFreeAt[freeWorker] = finish
      finishOf.set(best, finish)
      unstarted.delete(best)
      if (finish > makespan) makespan = finish
    }

    if (unstarted.size === 0) break

    const nextTime = Math.min(...workerFreeAt.filter((freeAt) => freeAt > time))
    time = nextTime
  }

  return { workerLog, makespan }
}
"}

