/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseGraph } from './parser.js'
import { checkForCycle, computeTimings, computePriorities, buildDependents } from './graph.js'
import { packSchedule } from './scheduler.js'
import { CliError, usageError, workersError } from './errors.js'

const WORKERS_PATTERN = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_PATTERN.test(argv[1])) throw workersError()
    return { mode: 'pack', workers: Number.parseInt(argv[1], 10) }
  }
  throw usageError()
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EOF') break
      throw error
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function formatWaves(costs, timings) {
  const byDepth = new Map()
  for (const [name, timing] of timings) {
    if (!byDepth.has(timing.depth)) byDepth.set(timing.depth, [])
    byDepth.get(timing.depth).push(name)
  }
  const maxDepth = byDepth.size === 0 ? -1 : Math.max(...byDepth.keys())
  const lines = []
  for (let depth = 0; depth <= maxDepth; depth += 1) {
    const names = (byDepth.get(depth) ?? []).sort()
    lines.push(`wave ${depth}: ${names.join(' ')}`)
  }
  const total = timings.size === 0 ? 0 : Math.max(...[...timings.values()].map((t) => t.finish))
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatExplain(costs, timings) {
  const names = [...costs.keys()].sort()
  const lines = names.map((name) => {
    const t = timings.get(name)
    return `${name} start=${t.start} finish=${t.finish} depth=${t.depth}`
  })
  const total = timings.size === 0 ? 0 : Math.max(...[...timings.values()].map((t) => t.finish))
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatPack(workerLog, makespan) {
  const lines = workerLog.map((entries, index) => {
    const parts = entries.map((e) => ` ${e.name}@${e.start}-${e.finish}`)
    return `worker ${index}:${parts.join('')}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const argv = process.argv.slice(2)
  let args
  try {
    args = parseArgs(argv)
  } catch (error) {
    if (error instanceof CliError) {
      process.stderr.write(error.message + '\n')
      process.exit(error.exitCode)
    }
    throw error
  }

  const input = readStdin()

  let costs
  let deps
  try {
    ;({ costs, deps } = parseGraph(input))
    checkForCycle(costs, deps)
  } catch (error) {
    if (error instanceof CliError) {
      process.stderr.write(error.message + '\n')
      process.exit(error.exitCode)
    }
    throw error
  }

  if (args.mode === 'waves') {
    const timings = computeTimings(costs, deps)
    process.stdout.write(formatWaves(costs, timings))
  } else if (args.mode === 'explain') {
    const timings = computeTimings(costs, deps)
    process.stdout.write(formatExplain(costs, timings))
  } else {
    const dependents = buildDependents(costs, deps)
    const priorities = computePriorities(costs, dependents)
    const { workerLog, makespan } = packSchedule(costs, deps, priorities, args.workers)
    process.stdout.write(formatPack(workerLog, makespan))
  }
}

main()
"}

